        "text": "The 2008 Global Financial Crisis Overview",
        "variant": "h1"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "The 2008 global financial crisis, often referred to as the Great Recession, was a severe worldwide economic crisis triggered by a collapse in the U.S. housing market. Its primary causes were deeply rooted in a combination of risky lending practices and inadequate financial regulation, leading to widespread systemic failure."
      },
      "children": []
    },
    "causes_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "causes_header_stack",
